-- Doctor practice payment gateway. Financially isolated from subscription_payments.
create table if not exists public.doctor_payment_settings (id uuid primary key default gen_random_uuid(),owner_doctor_id uuid not null unique references public.doctor_profiles(id) on delete cascade,cash_enabled boolean not null default true,online_payment_enabled boolean not null default false,provider text not null default 'SSLCOMMERZ' check(provider='SSLCOMMERZ'),environment text not null default 'SANDBOX' check(environment='SANDBOX'),store_identifier text,bangla_qr_status text not null default 'MERCHANT_ACTIVATION_REQUIRED',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.practice_payment_transactions (id uuid primary key default gen_random_uuid(),owner_doctor_id uuid not null references public.doctor_profiles(id) on delete cascade,practice_location_id uuid not null references public.practice_locations(id) on delete restrict,practice_payment_id uuid unique references public.practice_payments(id) on delete set null,appointment_id uuid,encounter_id uuid,provider text not null default 'SSLCOMMERZ' check(provider='SSLCOMMERZ'),merchant_transaction_id text not null unique,provider_transaction_id text,amount numeric(12,2) not null check(amount>0),currency text not null default 'BDT' check(currency='BDT'),payment_channel text,status text not null default 'PENDING' check(status in('PENDING','PAID','FAILED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED')),refund_amount numeric(12,2) not null default 0 check(refund_amount>=0 and refund_amount<=amount),verified_at timestamptz,failed_at timestamptz,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists practice_payment_tx_doctor_idx on public.practice_payment_transactions(owner_doctor_id,created_at desc); create index if not exists practice_payment_tx_location_idx on public.practice_payment_transactions(practice_location_id,created_at desc); create unique index if not exists practice_payment_tx_provider_ref_uq on public.practice_payment_transactions(provider,provider_transaction_id) where provider_transaction_id is not null;
alter table public.doctor_payment_settings enable row level security; alter table public.practice_payment_transactions enable row level security; revoke all on public.doctor_payment_settings from anon; revoke all on public.practice_payment_transactions from anon; grant select,insert,update on public.doctor_payment_settings to authenticated; grant select,insert on public.practice_payment_transactions to authenticated;
drop policy if exists doctor_payment_settings_owner on public.doctor_payment_settings; create policy doctor_payment_settings_owner on public.doctor_payment_settings for all to authenticated using(owner_doctor_id=public.resolve_doctor_profile_id_for_actor(auth.uid())) with check(owner_doctor_id=public.resolve_doctor_profile_id_for_actor(auth.uid()));
drop policy if exists practice_payment_transactions_owner_read on public.practice_payment_transactions; create policy practice_payment_transactions_owner_read on public.practice_payment_transactions for select to authenticated using(owner_doctor_id=public.resolve_doctor_profile_id_for_actor(auth.uid()));
drop policy if exists practice_payment_transactions_owner_insert on public.practice_payment_transactions; create policy practice_payment_transactions_owner_insert on public.practice_payment_transactions for insert to authenticated with check(owner_doctor_id=public.resolve_doctor_profile_id_for_actor(auth.uid()) and status='PENDING' and practice_payment_id is null and provider='SSLCOMMERZ' and currency='BDT' and exists(select 1 from public.practice_locations pl where pl.id=practice_location_id and pl.owner_doctor_id=owner_doctor_id));
create or replace function public.transition_practice_gateway_payment(target_merchant_transaction_id text,target_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if target_status not in('FAILED','CANCELLED') then raise exception 'invalid transition'; end if; update public.practice_payment_transactions set status=target_status,failed_at=case when target_status='FAILED' then now() else failed_at end,cancelled_at=case when target_status='CANCELLED' then now() else cancelled_at end,updated_at=now() where merchant_transaction_id=target_merchant_transaction_id and status='PENDING'; end $$; revoke all on function public.transition_practice_gateway_payment(text,text) from public,anon,authenticated; grant execute on function public.transition_practice_gateway_payment(text,text) to service_role;
create or replace function public.reconcile_practice_gateway_payment(target_merchant_transaction_id text,target_provider_transaction_id text,target_amount numeric,target_currency text,target_payment_channel text) returns table(status text,amount text,currency text) language plpgsql security definer set search_path=public,pg_temp as $$ declare tx public.practice_payment_transactions%rowtype; payment_id uuid; begin select * into tx from public.practice_payment_transactions where merchant_transaction_id=target_merchant_transaction_id for update; if not found then return query select 'UNKNOWN'::text,null::text,null::text; return; end if; if tx.amount<>target_amount or tx.currency<>target_currency or target_currency<>'BDT' then return query select 'MISMATCH'::text,tx.amount::text,tx.currency; return; end if; if tx.status='PAID' and tx.practice_payment_id is not null then return query select 'PAID'::text,tx.amount::text,tx.currency; return; end if; if tx.status<>'PENDING' then return query select tx.status,tx.amount::text,tx.currency; return; end if; insert into public.practice_payments(owner_doctor_id,practice_location_id,payment_date,gross_amount,paid_amount,refunded_amount,method,status,note) values(tx.owner_doctor_id,tx.practice_location_id,current_date,tx.amount,tx.amount,0,'OTHER','PAID','SSLCOMMERZ · '||coalesce(nullif(target_payment_channel,''),'Online')) returning id into payment_id; update public.practice_payment_transactions set status='PAID',practice_payment_id=payment_id,provider_transaction_id=nullif(target_provider_transaction_id,''),payment_channel=nullif(target_payment_channel,''),verified_at=now(),updated_at=now() where id=tx.id; return query select 'PAID'::text,tx.amount::text,tx.currency; exception when unique_violation then select * into tx from public.practice_payment_transactions where merchant_transaction_id=target_merchant_transaction_id; return query select tx.status,tx.amount::text,tx.currency; end $$; revoke all on function public.reconcile_practice_gateway_payment(text,text,numeric,text,text) from public,anon,authenticated; grant execute on function public.reconcile_practice_gateway_payment(text,text,numeric,text,text) to service_role;
